mapper.select:
select  from asm_device_change_record


        and logic_device_unique_id = #{logicDeviceUniqueId}


        and attr_id = #{attrId}


        and occurred_at between #{beginTime, typeHandler=com.ecat.integration.EnvAirStationManagerIntegration.support.TimestamptzInstantTypeHandler} and #{endTime, typeHandler=com.ecat.integration.EnvAirStationManagerIntegration.support.TimestamptzInstantTypeHandler}


order by occurred_at desc
